    """LATE_FEES_PAUSE as a boolean (1/0, yes/no, true/false, on/off).

    Unset or empty: the value of the file. Anything else is an error, so that a
    typo never pauses the billing silently (nor fails to pause it).
    """
    raw = os.environ.get("LATE_FEES_PAUSE", "").strip()
    if not raw:
        return file_value
